class Validators{static required(e,t){return null==e||""===e?`Поле "${t}" обязательно`:"string"==typeof e&&""===e.trim()?`Поле "${t}" не может быть пустым`:null}static amount(e){const t=parseFloat(e);if(isNaN(t))return"Сумма должна быть числом";if(t<=0)return"Сумма должна быть больше 0";if(t>9999999.99)return"Сумма слишком большая (макс: 9 999 999.99)";const r=e.toString().split(".")[1];return r&&r.length>2?"Максимум 2 знака после запятой":null}static date(e){if(!e)return"Дата обязательна";const t=e instanceof Date?e:new Date(e),r=new Date;return r.setHours(23,59,59,999),isNaN(t.getTime())?"Неверный формат даты":t>r?"Дата не может быть в будущем":null}static maxLength(e,t,r){return e&&e.length>t?`Поле "${r}" не должно превышать ${t} символов`:null}static minLength(e,t,r){return e&&e.length<t?`Поле "${r}" должно содержать минимум ${t} символов`:null}static email(e){if(!e)return null;return/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e)?null:"Неверный формат email"}static positiveNumber(e){const t=parseFloat(e);return isNaN(t)?"Должно быть числом":t<=0?"Должно быть положительным числом":null}static validateForm(e,t){const r={};for(const[n,o]of Object.entries(t)){const t=e[n];for(const e of o){const o=e(t);if(o){r[n]=o;break}}}return Object.keys(r).length>0?r:null}static showFormErrors(e,t="form"){if(document.querySelectorAll(".error-message").forEach((e=>e.remove())),document.querySelectorAll(".input-error").forEach((e=>e.classList.remove("input-error"))),e)for(const[t,r]of Object.entries(e)){const e=document.querySelector(`[name="${t}"]`);if(e){e.classList.add("input-error");const t=document.createElement("div");t.className="error-message",t.textContent=r,e.parentNode.insertBefore(t,e.nextSibling)}}}static clearFormErrors(e="form"){document.querySelectorAll(".error-message").forEach((e=>e.remove())),document.querySelectorAll(".input-error").forEach((e=>e.classList.remove("input-error")))}}